/**
 * Sprite sheets in Aseprite's JSON format ("json-array" with frameTags).
 *
 * Every tag is an animation (or a single pose) of one or more frames, each with its own
 * duration. The sheets are generated by tools/build_blob_sprites.py, but they can just as well be
 * edited in Aseprite and exported with
 * `--sheet x.png --data x.json --format json-array --list-tags`.
 */

import { Image, type Color } from "./image";
import { decodePng } from "./png";

interface FrameData {
  frame: { x: number; y: number; w: number; h: number };
  duration?: number;
}

/** What the .json file of a sheet holds. */
export interface SheetData {
  frames: FrameData[] | Record<string, FrameData>;
  meta: {
    image: string;
    frameTags: { name: string; from: number; to: number }[];
    faceTop?: number;
    faceCenter?: string;
  };
}

export class Sheet {
  /** Per tag its frames, each with its duration in seconds. */
  private readonly tags = new Map<string, [Image, number][]>();
  /** Optional: how far the face sits below the first wide row. */
  readonly faceTop: number | null;
  /** Optional: "bottom" centers the face on the bottom row (see faceAnchor). */
  readonly faceCenter: string | null;

  /** `data`: the content of the .json file; `image`: the picture it names, or the PNG file itself. */
  constructor(data: SheetData, image: Image | Uint8Array) {
    const picture = image instanceof Image ? image : decodePng(image);
    const frames = Array.isArray(data.frames) ? data.frames : Object.values(data.frames); // Aseprite "json-hash"
    const images = frames.map(({ frame, duration }): [Image, number] =>
      [picture.crop(frame.x, frame.y, frame.x + frame.w, frame.y + frame.h), Math.max(1, duration ?? 100) / 1000]);
    for (const tag of data.meta.frameTags) {
      this.tags.set(tag.name, images.slice(tag.from, tag.to + 1));
    }
    this.faceTop = data.meta.faceTop ?? null;
    this.faceCenter = data.meta.faceCenter ?? null;
  }

  has(tag: string): boolean {
    return this.tags.has(tag);
  }

  /** [image, index] of the frame that is due at time t (seconds, loops forever). */
  frame(tag: string, t = 0.0): [Image, number] {
    const frames = this.framesOf(tag);
    if (frames.length === 1) {
      return [frames[0][0], 0];
    }
    t %= frames.reduce((sum, [, duration]) => sum + duration, 0);
    for (let i = 0; i < frames.length; i++) {
      if (t < frames[i][1]) {
        return [frames[i][0], i];
      }
      t -= frames[i][1];
    }
    return [frames.at(-1)![0], frames.length - 1];
  }

  image(tag: string): Image {
    return this.framesOf(tag)[0][0];
  }

  private framesOf(tag: string): [Image, number][] {
    const frames = this.tags.get(tag);
    if (!frames) {
      throw new Error(`The sprite sheet has no "${tag}"`);
    }
    return frames;
  }
}

/** The first row of a figure that is at least 8 pixels wide (0 if there is none), and all its rows. */
export function wideRow(image: Image): [number, number[][]] {
  const rows = Array.from({ length: image.height }, (_, y) => image.filled(y));
  return [Math.max(0, rows.findIndex((xs) => xs.length >= 8)), rows];
}

/**
 * Where the face sits on a body frame: [center x, top row].
 *
 * The body proper starts at the first row that is at least 8 pixels wide (the curl on top doesn't
 * count). The face sits just under a third of the body height below that – so it moves along by
 * itself when the body is squashed or stretched. If the sheet sets `faceTop` (e.g. Sneezle: face
 * in the head rather than the belly), it sits that many rows below that row. It is centered on
 * its own row, or with `center = "bottom"` on the feet, the bottom two rows (Sneezle: handle and
 * spout stick out to the sides further up), or with `center = "left"` on the first stretch of its own row from the
 * left (Kitlet: its tail stands apart from its body on the right).
 */
export function faceAnchor(body: Image, faceTop: number | null = null, center: string | null = null): [number, number] {
  const [top, rows] = wideRow(body);
  const filled = rows.map((xs, y) => (xs.length ? y : -1)).filter((y) => y >= 0);
  const bottom = filled.length ? Math.max(...filled) : body.height - 1;
  const y = top + (faceTop ?? Math.round((bottom - top + 1) * 0.32));
  const own = rows[Math.min(y, body.height - 1)];
  // on the feet: the bottom two rows, so that a foot lifted for a step still counts
  const feet = [...rows[bottom], ...(rows[bottom - 1] ?? [])].sort((a, b) => a - b);
  const xs = center === "bottom" || !own.length ? feet
    : center === "left" ? own.filter((x, i) => x - own[0] === i) : own;
  return [(xs[0] + xs.at(-1)! + 1) / 2, y];
}

// Hue, saturation and value of a color and back, each 0–255.

function hsvOf(r: number, g: number, b: number): [number, number, number] {
  const maxc = Math.max(r, g, b);
  const minc = Math.min(r, g, b);
  if (minc === maxc) {
    return [0, 0, maxc];
  }
  const cr = maxc - minc;
  const rc = (maxc - r) / cr;
  const gc = (maxc - g) / cr;
  const bc = (maxc - b) / cr;
  const h = r === maxc ? bc - gc : g === maxc ? 2.0 + rc - bc : 4.0 + gc - rc;
  return [Math.trunc(((h / 6.0 + 1.0) % 1.0) * 255.0), Math.trunc(cr / maxc * 255.0), maxc];
}

function rgbOf(h: number, s: number, v: number): readonly [number, number, number] {
  if (s === 0) {
    return [v, v, v];
  }
  const i = Math.floor(h * 6.0 / 255.0);
  const rest = h * 6.0 / 255.0 - i;
  const fs = s / 255.0;
  const p = Math.round(v * (1.0 - fs));
  const q = Math.round(v * (1.0 - fs * rest));
  const t = Math.round(v * (1.0 - fs * (1.0 - rest)));
  return ([[v, t, p], [q, v, p], [p, v, t], [p, q, v], [t, p, v], [v, p, q]] as const)[i % 6];
}

/**
 * Shift the hue of all saturated pixels in the range hueFrom..hueTo (0–255).
 *
 * For the sick blob: teal → toxic green, eyes and mouth stay as they are. (Every other color
 * goes to hue, saturation and value and back as well, which can move it by one.)
 */
export function recolor(image: Image, hueFrom: number, hueTo: number, shift: number): Image {
  const out = image.copy();
  const data = out.data;
  for (let i = 0; i < data.length; i += 4) {
    let [h, s, v] = hsvOf(data[i], data[i + 1], data[i + 2]);
    if (hueFrom <= h && h <= hueTo && s > 60) {
      h = (((h + shift) % 256) + 256) % 256;
    }
    [data[i], data[i + 1], data[i + 2]] = rgbOf(h, s, v);
  }
  return out;
}

/** Replace exact colors: pairs of [from, to]. For the bulb of the child's lure. */
export function swapColors(image: Image, colors: readonly (readonly [Color, Color])[]): Image {
  const out = image.copy();
  const data = out.data;
  for (let i = 0; i < data.length; i += 4) {
    if (!data[i + 3]) {
      continue;
    }
    const match = colors.find(([from]) => from[0] === data[i] && from[1] === data[i + 1] && from[2] === data[i + 2]);
    if (match) {
      data.set(match[1], i);
    }
  }
  return out;
}

/**
 * One-pixel outline (no diagonals), so the figure stands out against any sky on the matrix. The
 * image grows by 1 pixel on every side.
 */
export function outline(image: Image, color: Color = [0, 0, 0]): Image {
  const padded = new Image(image.width + 2, image.height + 2);
  padded.blit(image, 1, 1);
  const solid = (x: number, y: number) =>
    x >= 0 && x < padded.width && y >= 0 && y < padded.height && padded.alpha(x, y) >= 128;
  const out = new Image(padded.width, padded.height);
  for (let y = 0; y < out.height; y++) {
    for (let x = 0; x < out.width; x++) {
      if (solid(x, y) || solid(x - 1, y) || solid(x + 1, y) || solid(x, y - 1) || solid(x, y + 1)) {
        out.point(x, y, color);
      }
    }
  }
  out.alphaComposite(padded);
  return out;
}

/** Blend with a color (e.g. a sickly pale), keeping transparency. */
export function tint(image: Image, color: Color, amount: number): Image {
  const out = image.copy();
  for (let i = 0; i < out.data.length; i += 4) {
    for (let c = 0; c < 3; c++) {
      out.data[i + c] = Math.trunc(out.data[i + c] + amount * (color[c] - out.data[i + c]));
    }
  }
  return out;
}
